  ('ficha-alumno', 'Certificados y constancias', 'Ficha de alumno y constancia de matriculación', 'La ficha de alumno es tu reporte académico oficial; la piden para becas, constancias y equivalencias. En el mismo formulario podés pedir la constancia de matriculación y otras constancias.', array['Completá el formulario de ficha de alumno / constancia de matriculación.', 'Mandalo a la Dirección Académica o presentalo en la Mesa de Entrada.']::text[], array['Formulario de solicitud completo y firmado']::text[], null, 'Dirección Académica de la FCQ.', null, 'constancia@qui.una.py · documentos.acad@qui.una.py', 'mixto', 'https://www.qui.una.py/v3/wp-content/uploads/2026/06/SOLICITUD-DE-FICHA-DE-ALUMNO_CONSTANCIA-DE-MATRICULACION-Y-OTRAS-CONSTANCIAS.pdf', 'https://www.qui.una.py/academico/formatos-y-formularios-2/', 170),
  ('autenticacion-certificado', 'Certificados y constancias', 'Autenticación de certificado de estudios', 'Para autenticar copias de tu certificado de estudios.', array['Completá el formulario de autenticación.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado']::text[], 'Consultá en Mesa de Entrada si corresponde arancel.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', null, 'secgen@qui.una.py · (021) 729 0030', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/05-Solicitud-de-Autenticacion-de-Certificado-de-Estudios.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 180),
  ('antecedentes-disciplinarios', 'Certificados y constancias', 'Constancia de antecedentes disciplinarios', 'Constancia de que no tenés (o de cuáles son) tus antecedentes disciplinarios en la FCQ.', array['Completá el formulario.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado']::text[], 'Consultá en Mesa de Entrada si corresponde arancel.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', null, 'secgen@qui.una.py · (021) 729 0030', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/04-Solicitud-de-Constancia-de-Antecedentes-Disciplinarios-1.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 190),
  ('programas-asignaturas', 'Certificados y constancias', 'Programas de materias', 'Copia oficial de los programas de las materias (sirven para convalidar en otra universidad o para movilidad).', array['Completá el formulario de solicitud de programas de asignaturas.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado']::text[], 'Consultá en Mesa de Entrada si corresponde arancel.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', null, 'documentos.acad@qui.una.py (solicitudes) · acade@qui.una.py', 'presencial', 'https://qui.una.py/wp-content/uploads/2022/10/17.-Solicitud-de-programas-de-asignaturas-2022-Version-1-copia.docx', 'https://www.qui.una.py/academico/formatos-y-formularios-2/', 200),
  ('copia-documentos', 'Certificados y constancias', 'Fotocopia simple de documentos', 'Para pedir copia simple de documentos que están en tu legajo.', array['Completá el formulario.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado']::text[], 'Consultá en Mesa de Entrada si corresponde arancel.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', null, 'secgen@qui.una.py · (021) 729 0030', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/06-Solicitud-de-copia-simple.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 210),
  ('homologacion', 'Cambios de carrera y equivalencias', 'Homologación de materias', 'Para que una materia aprobada en otra carrera o plan de la FCQ te cuente en tu carrera actual. Lleva el visto bueno de la Coordinación de Carrera.', array['Completá el formulario con las materias a homologar y las aprobadas, con su nivel.', 'Juntá las fichas de alumno de las dos carreras y el recibo del arancel.', 'Poné todo en una carpeta archivadora y presentala en la Mesa de Entrada.']::text[], array['Formulario de solicitud completo y firmado', 'Fotocopia de la cédula vigente (frente y dorso)', 'Recibo de pago del arancel', 'Ficha de alumno de la carrera donde querés homologar', 'Ficha de alumno de la carrera donde aprobaste las materias', 'Todo en una carpeta archivadora']::text[], 'Arancel según la resolución de aranceles vigente. Se paga en Perceptoría (perceptoria@qui.una.py) y se adjunta el recibo.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Hasta el 20/02/2026 (1.er semestre) y el 31/07/2026 (2.º semestre).', 'documentos.acad@qui.una.py (solicitudes) · acade@qui.una.py', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/11-Solicitud-de-Homologacion-de-Asignaturas.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 220),
  ('convalidacion', 'Cambios de carrera y equivalencias', 'Convalidación de materias', 'Para que materias aprobadas en otra facultad o universidad te cuenten en tu carrera de la FCQ.', array['Completá el formulario con las materias a convalidar y las aprobadas en la otra institución.', 'Adjuntá los documentos que pide el formulario (certificado de estudios y programas de la otra institución).', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado', 'Fotocopia de la cédula vigente (frente y dorso)', 'Recibo de pago del arancel']::text[], 'Arancel según la resolución de aranceles vigente. Se paga en Perceptoría (perceptoria@qui.una.py) y se adjunta el recibo.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Hasta el 20/02/2026 (1.er semestre) y el 31/07/2026 (2.º semestre).', 'documentos.acad@qui.una.py (solicitudes) · acade@qui.una.py', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/12-Solicitud-de-Convalidacion-de-Asignaturas.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 230),
  ('traslado-carrera', 'Cambios de carrera y equivalencias', 'Cambio de carrera dentro de la FCQ', 'Traslado de una carrera de la FCQ a otra.', array['Completá el formulario de traslado de carrera.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.', 'Después pedí la homologación de las materias que ya aprobaste.']::text[], array['Formulario de solicitud completo y firmado', 'Fotocopia de la cédula vigente (frente y dorso)', 'Recibo de pago del arancel', 'Ficha de alumno de la carrera original (donde obtuviste la ciudadanía universitaria)']::text[], 'Arancel según la resolución de aranceles vigente. Se paga en Perceptoría (perceptoria@qui.una.py) y se adjunta el recibo.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Hasta el 20/02/2026 (1.er semestre) y el 31/07/2026 (2.º semestre).', 'documentos.acad@qui.una.py (solicitudes) · acade@qui.una.py', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/14-Solicitud-de-Traslado-de-Carrera-de-la-FCQ-UNA.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 240),
  ('traslado-externo', 'Cambios de carrera y equivalencias', 'Traslado desde otra facultad o universidad', 'Para estudiantes de otra unidad académica de la UNA, de otra universidad nacional o del exterior que quieren pasar a la FCQ.', array['Completá el formulario de traslado.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado', 'Fotocopia de la cédula vigente (frente y dorso)', 'Recibo de pago del arancel']::text[], 'Arancel según la resolución de aranceles vigente. Se paga en Perceptoría (perceptoria@qui.una.py) y se adjunta el recibo.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Hasta el 20/02/2026 (1.er semestre) y el 31/07/2026 (2.º semestre).', 'documentos.acad@qui.una.py (solicitudes) · acade@qui.una.py', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/15-Solicitud-de-Traslado-de-otras-Universidades-o-de-la-UNA.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 250),
  ('traslado-plan', 'Cambios de carrera y equivalencias', 'Cambio de plan académico', 'Para pasar de un plan de estudios a otro de tu misma carrera (por ejemplo, del 2018 al 2026). La tabla de equivalencias 2018 a 2026 todavía no está publicada: consultala en la Dirección Académica antes de decidir.', array['Consultá en la Dirección Académica cómo quedan tus materias en el plan nuevo.', 'Completá el formulario de traslado de plan académico.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado']::text[], 'Consultá en Mesa de Entrada si corresponde arancel.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', null, 'documentos.acad@qui.una.py (solicitudes) · acade@qui.una.py', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/16-Solicitud-de-Traslado-de-Plan-Academico.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 260),
  ('matriculacion-simultanea', 'Cambios de carrera y equivalencias', 'Matriculación simultánea (dos carreras)', 'Para cursar dos carreras de la FCQ al mismo tiempo.', array['Completá el formulario de matriculación simultánea.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado']::text[], 'Consultá en Mesa de Entrada si corresponde arancel.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Hasta el 20/02/2026 (1.er semestre) y el 31/07/2026 (2.º semestre).', 'documentos.acad@qui.una.py (solicitudes) · acade@qui.una.py', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/13-Solicitud-de-Matriculacion-Simultanea-de-la-FCQ-UNA.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 270),
  ('prorroga-readmision', 'Cambios de carrera y equivalencias', 'Prórroga o readmisión a la carrera', 'El plazo máximo para terminar la carrera es el doble de su duración (Art. 11). Si lo superaste o tu matrícula se canceló, podés pedir prórroga, extensión de prórroga o readmisión.', array['Completá el formulario indicando si pedís prórroga, extensión o readmisión.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado', 'Fotocopia de la cédula vigente (frente y dorso)', 'Recibo de pago del arancel', 'Certificado de estudios o ficha de alumno (de la carrera donde se canceló la matrícula)', 'Si corresponde: resolución de prórroga o extensión anterior']::text[], 'Arancel según la resolución de aranceles vigente. Se paga en Perceptoría (perceptoria@qui.una.py) y se adjunta el recibo.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Hasta el 06/02/2026 (1.er semestre) y el 17/07/2026 (2.º semestre).', 'documentos.acad@qui.una.py (solicitudes) · acade@qui.una.py', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/21-Solicitud-de-Prorroga-Extension-de-Prorroga-o-Readmision-a-la-carrera.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 280),
  ('admision-directa', 'Cambios de carrera y equivalencias', 'Admisión directa para egresados', 'Para quienes ya tienen un título de grado y quieren entrar a otra carrera de la FCQ sin el examen de admisión. Hay un formulario distinto según de dónde egresaste: FCQ, otra facultad de la UNA o universidad nacional, universidad privada reconocida por el CONES, o universidad del extranjero.', array['Elegí el formulario que corresponde a tu universidad de egreso.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado']::text[], 'Consultá en Mesa de Entrada si corresponde arancel.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Hasta el 06/02/2026 (1.er semestre) y el 17/07/2026 (2.º semestre).', 'admision@qui.una.py · (021) 729 0030 int. 141', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/17-Solicitud-de-Admision-Directa-de-egresados-de-la-FCQ-UNA.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 290),
  ('exoneraciones', 'Becas y exoneraciones', 'Exoneración de cuotas', 'La FCQ exonera las cuotas por un semestre por: Ayuda al Estudio (categoría A promedio ≥ 4, B ≥ 3,5, C ≥ 3), Excelencia Estudiantil (desde 2.º nivel, hasta 4 por carrera), logros deportivos, culturales o de iniciación científica.', array['Elegí el formulario del tipo de exoneración que te corresponde.', 'Adjuntá lo que acredite tu promedio o tu logro.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado']::text[], 'Sin costo.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Hasta el 23/02/2026 (1.er semestre) y el 03/08/2026 (2.º semestre).', 'secgen@qui.una.py · (021) 729 0030', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/23-Solicitud-de-Exoneracion-de-Ayuda-al-Estudio.pdf', 'https://www.qui.una.py/becas/exoneraciones-becas/', 300),
  ('beca-rectorado', 'Becas y exoneraciones', 'Beca de grado del Rectorado', 'En 2026 la FCQ adjudicó 75 becas de grado de ₲ 2.000.000 cada una, en un solo pago. La convocatoria sigue el calendario del Rectorado.', array['Pedí la constancia de promedio y tu ficha de alumno firmada.', 'Completá la solicitud de beca y la declaración jurada de no tener otra beca.', 'Presentá todo junto en la Mesa de Entrada dentro del periodo de postulación.']::text[], array['Constancia de promedio no inferior a 3 (o estar en el 25 % de mejores promedios) del periodo anterior, habiendo aprobado al menos el 50 % de las materias cursadas. Ingresantes: 80 % o más en el examen de admisión.', 'Fotocopia de la cédula vigente (frente y dorso), nacionalidad paraguaya', 'Ficha de alumno o reporte de notas del año anterior, firmado', 'Declaración jurada de no tener otra beca en el periodo']::text[], 'Sin costo.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Postulación 2026: del 11/05 al 15/06, hasta las 18:00.', 'secgen@qui.una.py · (021) 729 0030', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/01-Solicitud-de-Beca-de-Grado-2026.pdf', 'https://www.qui.una.py/becas/becas-del-rectorado/', 310),
  ('auxiliar-ensenanza', 'Becas y exoneraciones', 'Ayudante de cátedra (Auxiliar de la Enseñanza IV)', 'Para ser ayudante de cátedra no remunerado. Da derecho a exoneración de cuotas según la categoría.', array['Completá el formulario de nombramiento de Auxiliar de la Enseñanza IV.', 'Presentá el formulario y los documentos en la Mesa de Entrada. Si falta algo, no lo reciben.']::text[], array['Formulario de solicitud completo y firmado']::text[], 'El formulario no pide recibo de pago.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', 'Hasta el 20/02/2026 (1.er semestre) y el 31/07/2026 (2.º semestre).', 'documentos.acad@qui.una.py (solicitudes) · acade@qui.una.py', 'presencial', 'https://www.qui.una.py/v2/wp-content/uploads/27-Solicitud-de-nombramiento-de-Auxiliar-de-la-Ensenanza-IV.pdf', 'https://www.qui.una.py/institucional/formularios-institucional/', 320),
  ('titulo-grado', 'Egreso y título', 'Título de grado', 'Al terminar la carrera, el título se expide en la FCQ y se registra según las normas de la UNA y del Ministerio de Educación (Res. MEC 2424/06). La FCQ no publica el paso a paso: pedí la lista de requisitos actualizada en la Secretaría antes de empezar.', array['Verificá en la Dirección Académica que tengas todas las materias, seminarios, pasantías y el trabajo de grado aprobados.', 'Pedí en la Secretaría de la Facultad la lista de requisitos y aranceles para la expedición del título.', 'Presentá los documentos en la Mesa de Entrada y seguí el trámite hasta el registro.']::text[], array['Todas las obligaciones académicas aprobadas', 'Estar al día con las obligaciones administrativas y financieras']::text[], 'Arancel según la resolución de aranceles vigente. Se paga en Perceptoría (perceptoria@qui.una.py) y se adjunta el recibo.', 'Mesa de Entrada de la Secretaría de la Facultad (sede central, San Lorenzo). Lunes a viernes, 07:00 a 18:00.', null, 'secgen@qui.una.py · (021) 729 0030', 'presencial', null, 'https://www.qui.una.py/academico/reglamentaciones-2/', 330),
  ('correo-institucional', 'Servicios', 'Correo institucional', 'Cuenta @una.py con Microsoft 365 (Word, Excel, PowerPoint en línea) y 100 GB en OneDrive, además de acceso a bibliotecas virtuales y bases de datos.', array['Entrá a e-Trámite (tramites.una.py) y creá tu usuario si no tenés.', 'Elegí "QUI - Facultad de Ciencias Químicas".', 'En "Mis Trámites", elegí "Creación de Correo Institucional (Estudiante de Grado)".', 'Descargá los documentos, completalos y subilos en PDF.', 'Te llegan las indicaciones y la contraseña al correo personal que registraste.']::text[], array['Formulario de solicitud completo y firmado', 'Cédula vigente digitalizada (frente y dorso)', 'Contrato de adhesión completo y firmado']::text[], 'Sin costo.', 'En línea, por e-Trámite de la UNA.', 'Demora hasta 5 días hábiles.', null, 'etramite', 'https://tramites.una.py/', 'https://www.qui.una.py/solicitud-de-correo-institucional-para-estudiantes/', 340),
  ('carnet-biblioteca', 'Servicios', 'Carnet de biblioteca', 'Para retirar libros de la biblioteca de la FCQ.', array['Completá la solicitud de carnet de biblioteca.', 'Presentala en la Biblioteca (lunes a viernes, 07:00 a 19:00).']::text[], array['Formulario de solicitud completo y firmado']::text[], null, 'Biblioteca de la FCQ. Lunes a viernes, 07:00 a 19:00.', null, 'biblioteca@qui.una.py', 'presencial', 'https://qui.una.py/wp-content/uploads/2020/06/24.-Solicitud-de-carnet-de-biblioteca-2022_vDA.pdf', 'https://www.qui.una.py/academico/formatos-y-formularios-2/', 350)
on conflict (clave) do nothing;
